contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint am) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        // Make C's LogFile point at this contract: our fallback accepts any call,
        // including Log.AddMessage, so Put can complete.
        c.SetLogFile(address(this));
        c.SetMinSum(1);
        c.Initialized();
        // Deposit via fallback -> Put(0): records amount and sets unlockTime = now.
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        (, uint bb) = c.Acc(address(this));
        require(bb >= amount);
        require(am <= bb);
        uint cb = address(c).balance;
        // unlockTime == current block.timestamp, so block.timestamp > unlockTime is false:
        // Collect takes the 'no' branch and must neither revert nor change any state.
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        (, uint ba) = c.Acc(address(this));
        uint ca = address(c).balance;
        assert(!reverted && ba == bb && ca == cb);
    }
    receive() external payable {}
    fallback() external payable {}
}

