    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        uint balBefore = address(c).balance;
        bool reverted;
        try c.Collect(amount) { reverted = false; }
        catch { reverted = true; }
        assert(!reverted && address(c).balance <= balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint lockTime, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.Put{value: amount}(lockTime);
        uint bal = c.Acc(address(this));
        assert(bal == amount);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        uint balAfter = c.Acc(address(this));
        assert(reverted && balAfter == bal);
    }
    receive() external payable {}
}

