        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        (uint unlockAfter, uint balAfter) = c.Acc(address(this));
        assert(reverted && balAfter == balBefore && unlockAfter == unlockBefore);
    }
    receive() external payable {}
}

