contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint v, uint m, uint am) public payable {
        require(m > 0);
        require(am > 0);
        require(am <= v);
        require(address(this).balance >= v);
        c.SetLogFile(address(this));
        c.SetMinSum(m);
        c.Put{value: v}(0);
        (, uint balBefore) = c.Acc(address(this));
        uint ethBefore = address(c).balance;
        c.Collect(am);
        (, uint balAfter) = c.Acc(address(this));
        assert(balBefore == balAfter + am && ethBefore == address(c).balance + am);
    }
    receive() external payable {}
}
